PROGRAM ST450_SVARVBETJANING
VAR
    steg        : INT := 0;
    tmrSpann    : TON;
    trigReset   : R_TRIG;
    xLarm       : BOOL := FALSE;
    xKravOmstart: BOOL := TRUE;
    xDriftsklar : BOOL := FALSE;
    xSpann      : BOOL := FALSE; (* sekvensens spannkommando; utgangen skrivs pa ett stalle *)
END_VAR

(* EMG_OK kommer fran en certifierad sakerhets-PLC och lases bara. Logiken har
   ror inte sjalva sakerhetsfunktionen; den ar forreglad AV den. *)
trigReset(CLK := SYS_RESET);

IF NOT EMG_OK THEN
    xKravOmstart := TRUE;
END_IF;

(* Spanntrycket domes forst nar chucken haft sin spanntid 0,8 s pa sig.
   Under uppbyggnaden star trycket lagre an fonstret, och en vakt som domer
   for tidigt faller varje normal cykel pa tryckuppbyggnaden. *)
tmrSpann(IN := ST450_CHK_CLAMP, PT := T#800ms);
IF tmrSpann.Q AND (ST450_CHK_PRS < 25.0 OR ST450_CHK_PRS > 35.0) THEN
    xLarm := TRUE;
END_IF;

(* Slapper chucken medan spindeln roterar ar navet en kastad projektil. *)
IF ST450_SPN_RUN AND NOT ST450_CHK_CLAMPED THEN
    xLarm := TRUE;
END_IF;

(* Aterstallning kraver en stigande flank pa SYS_RESET. Att slappa upp
   nodstoppsdonet startar ingenting (IEC 60204-1:2016 9.2.3.4.2). *)
IF trigReset.Q AND EMG_OK AND AIR_OK THEN
    xLarm := FALSE;
    xKravOmstart := FALSE;
END_IF;

SYS_ALARM := xLarm;

xDriftsklar := EMG_OK AND AIR_OK AND SYS_AUTO AND NOT xLarm AND NOT xKravOmstart;

(* Vid larm och nodstopp nollstalls varje kommenderat don UTOM spanningen.
   ST450_CHK_CLAMP behaller sitt varde med flit: en chuck som slapper nar
   strommen gar slapper ett roterande nav (ISO 23125:2015 5.2.3). *)
IF NOT xDriftsklar THEN
    ST450_CNV_RUN := FALSE;
    ST450_DOR_OPEN := FALSE;
    ST450_CHK_UNCLAMP := FALSE;
    ST450_CYC_START := FALSE;
    ST450_RB_START := FALSE;
    steg := 0;
ELSE
    ST450_CNV_RUN := TRUE;
    CASE steg OF
        0:
            (* Detalj framme och spindeln stilla: oppna luckan. *)
            ST450_CYC_START := FALSE;
            IF ST450_PRT_PRS AND NOT ST450_SPN_RUN THEN
                ST450_DOR_OPEN := TRUE;
                steg := 1;
            END_IF;
        1:
            (* Chucken far slappa forst nar luckan STATT oppen och spindeln
               star stilla. Kommandot ar inte ett andlage. *)
            IF ST450_DOR_OPENED AND NOT ST450_SPN_RUN THEN
                xSpann := FALSE;
                ST450_CHK_UNCLAMP := TRUE;
                steg := 2;
            END_IF;
        2:
            IF NOT ST450_CHK_CLAMPED THEN
                ST450_CHK_UNCLAMP := FALSE;
                ST450_RB_START := TRUE;
                steg := 3;
            END_IF;
        3:
            IF ST450_RB_DONE THEN
                ST450_RB_START := FALSE;
                xSpann := TRUE;
                steg := 4;
            END_IF;
        4:
            (* Luckan stangs forst nar chucken bekraftat spanning och haft sin
               spanntid 0,8 s. *)
            IF ST450_CHK_CLAMPED AND tmrSpann.Q THEN
                ST450_DOR_OPEN := FALSE;
                steg := 5;
            END_IF;
        5:
            IF ST450_DOR_CLOSED AND ST450_CHK_CLAMPED THEN
                ST450_CYC_START := TRUE;
                steg := 6;
            END_IF;
        6:
            IF ST450_CYC_DONE THEN
                ST450_CYC_START := FALSE;
                steg := 0;
            END_IF;
    ELSE
        steg := 0;
    END_CASE;
END_IF;

(* Forreglingarna ligger efter sekvensen och domes varje scan. *)
IF ST450_SPN_RUN THEN
    ST450_CHK_UNCLAMP := FALSE;
    ST450_DOR_OPEN := FALSE;
END_IF;
(* Spannkommandot skrivs pa ETT stalle: sekvensens kommando forreglat mot
   slappventilen, sa att bada ventilerna aldrig star oppna i samma scan. *)
ST450_CHK_CLAMP := xSpann AND NOT ST450_CHK_UNCLAMP;
IF NOT ST450_CHK_CLAMPED THEN
    ST450_CYC_START := FALSE;
END_IF;
END_PROGRAM

